const items = $input.all();
const markdown = items[0].json.stdout || '';
const body = $('Webhook').item.json.body || {};
const skipCompleted = body.skip_completed !== undefined ? body.skip_completed : true;
const startCategory = body.start_category || '法定古蹟';
const startNumber = body.start_number || '00001';
const priorityBuildings = body.priority_buildings || [];
const categoryOrder = ['法定古蹟', '市區', '新界'];
const startCatIdx = categoryOrder.indexOf(startCategory);
if (startCatIdx === -1) startCatIdx = 0;
const sectionMap = {'法定古蹟':'法定古蹟','市區':'市區','新界':'新界'};
const sections = markdown.split(/^(?=### )/m);
const allParsed = [];
for (const section of sections) {
  const h = section.match(/^### (.+)/);
  if (!h) continue;
  const cat = sectionMap[h[1].trim()];
  if (!cat) continue;
  for (const line of section.split('\n')) {
    const t = line.trim();
    if (!t.startsWith('|') || t.includes('---') || t.includes('編號')) continue;
    const c = t.split('|'); c.shift(); c.pop();
    if (c.length < 10) continue;
    const bid = c[0].trim();
    if (!/^\d+$/.test(bid)) continue;
    allParsed.push({building_id: bid, category: cat, is_completed: c[8].trim().includes('已完成')});
  }
}
const pSet = new Set(priorityBuildings.map(String));
const pri = allParsed.filter(b => pSet.has(String(b.building_id)));
const rest = allParsed.filter(b => {
  const ci = categoryOrder.indexOf(b.category);
  if (ci < startCatIdx) return false;
  if (ci === startCatIdx && parseInt(b.building_id) < parseInt(startNumber)) return false;
  if (skipCompleted && b.is_completed) return false;
  if (pSet.has(String(b.building_id))) return false;
  return true;
});
return [...pri, ...rest].map(b => ({json: {building_id: b.building_id, category: b.category}}));

const items = $input.all();
const stdout = (items[0].json.stdout || '').toString();
const exitCode = items[0].json.exitCode;
const bid = $('逐建築物迭代').item.json.building_id;
let result = {building_id: bid, status: 'failed', verdict: 'failed'};
for (const line of stdout.split('\n')) {
  const t = line.trim();
  if (!t) continue;
  try {
    const p = JSON.parse(t);
    if (p.status === 'success' || p.verdict === 'passed') {
      result.status = 'passed';
      result.verdict = 'passed';
    }
    if (p.status === 'error') {
      result.status = 'failed';
      result.verdict = 'failed';
      result.error = p.error || 'unknown';
    }
  } catch(e) {}
}
if (exitCode !== 0 && result.status !== 'passed') {
  result.status = 'failed';
  result.verdict = 'failed';
}
return [{json: result}];
